svg.script:
//
(function() {
  const init = function() {
    const svg = document.getElementById("nmda-interactive-illustration");
    if (!svg || svg.dataset.initialized) return;
    svg.dataset.initialized = "true";

    const btnExcit = svg.querySelector("#btn-state-excit");
    const btnProt = svg.querySelector("#btn-state-prot");
    const hotspots = svg.querySelectorAll(".nmda-hotspot");
    const infoTexts = svg.querySelectorAll(".info-content");

    function setScene(state) {
      if (state === "protection") {
        svg.classList.add("protection-active");
        btnProt.setAttribute("aria-selected", "true");
        btnExcit.setAttribute("aria-selected", "false");

        // Define hotspot da memantina como ativo por padrão na cena de proteção
        hotspots.forEach(h => h.classList.remove("active-hs"));
        const memHs = svg.querySelector('[data-topic="memantina"]');
        if (memHs) memHs.classList.add("active-hs");
        showInfo("memantina");
      } else {
        svg.classList.remove("protection-active");
        btnExcit.setAttribute("aria-selected", "true");
        btnProt.setAttribute("aria-selected", "false");

        // Define hotspot do glutamato como ativo por padrão na cena de excitotoxicidade
        hotspots.forEach(h => h.classList.remove("active-hs"));
        const glutHs = svg.querySelector('[data-topic="glutamato"]');
        if (glutHs) glutHs.classList.add("active-hs");
        showInfo("glutamato");
      }
    }

    if (btnExcit && btnProt) {
      btnExcit.addEventListener("click", () => setScene("excitoxicity"));
      btnExcit.addEventListener("keydown", (e) => {
        if (e.key === "Enter" || e.key === " ") {
          setScene("excitoxicity");
          e.preventDefault();
        }
      });
      btnProt.addEventListener("click", () => setScene("protection"));
      btnProt.addEventListener("keydown", (e) => {
        if (e.key === "Enter" || e.key === " ") {
          setScene("protection");
          e.preventDefault();
        }
      });
    }

    hotspots.forEach(hs => {
      const select = function() {
        const topic = hs.getAttribute("data-topic");
        showInfo(topic);
        hotspots.forEach(h => h.classList.remove("active-hs"));
        hs.classList.add("active-hs");
      };
      hs.addEventListener("click", select);
      hs.addEventListener("keydown", (e) => {
        if (e.key === "Enter" || e.key === " ") {
          select();
          e.preventDefault();
        }
      });
    });

    function showInfo(topic) {
      infoTexts.forEach(txt => {
        if (txt.id === "info-" + topic) {
          txt.setAttribute("opacity", "1");
          txt.style.pointerEvents = "auto";
        } else {
          txt.setAttribute("opacity", "0");
          txt.style.pointerEvents = "none";
        }
      });
    }
  };

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", init);
  } else {
    init();
  }
})();
//
